#!/bin/bash
set -eu
exec >/dev/ttyS0 2>&1
echo ETZIO_HOST_PREFLIGHT_BEGIN_V1
python3 - <<'PY'
import fcntl, glob, json, os, pathlib, platform, subprocess

def read(path):
    try:
        return pathlib.Path(path).read_text().strip()
    except OSError as exc:
        return {"unavailable": type(exc).__name__}

def command(argv):
    try:
        result = subprocess.run(argv, capture_output=True, text=True, timeout=15, check=False)
        return {"exit_code": result.returncode, "stdout": result.stdout[:32768], "stderr": result.stderr[:4096]}
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"unavailable": type(exc).__name__}

data = {
    "schema": "etzio.host-preflight.observation.v1",
    "boundary": "benign host observation; not an admitted execution or storage profile",
    "kernel": platform.uname()._replace(node="omitted")._asdict(),
    "os_release": read("/etc/os-release"),
    "lscpu": command(["lscpu", "--json"]),
    "mounts": command(["findmnt", "--json", "--output", "TARGET,SOURCE,FSTYPE,OPTIONS"]),
    "devices": command(["lsblk", "--json", "--output", "NAME,TYPE,SIZE,FSTYPE,MODEL,ROTA"]),
    "cgroup_controllers": read("/sys/fs/cgroup/cgroup.controllers"),
    "ksm_run": read("/sys/kernel/mm/ksm/run"),
    "smt_active": read("/sys/devices/system/cpu/smt/active"),
    "nested_intel": read("/sys/module/kvm_intel/parameters/nested"),
    "cpu_vulnerabilities": {pathlib.Path(p).name: read(p) for p in glob.glob("/sys/devices/system/cpu/vulnerabilities/*")},
}
try:
    with open("/dev/kvm", "rb", buffering=0) as kvm:
        data["kvm_api_version"] = fcntl.ioctl(kvm.fileno(), 0xAE00, 0)
        vmfd = fcntl.ioctl(kvm.fileno(), 0xAE01, 0)
        os.close(vmfd)
        data["empty_kvm_vm_created_and_closed"] = True
except OSError as exc:
    data["kvm_error"] = {"type": type(exc).__name__, "errno": exc.errno}
print(json.dumps(data, sort_keys=True))
PY
echo ETZIO_HOST_PREFLIGHT_END_V1

